dw:transform-message.dw:set-payload:
%dw 2.0
output application/json
fun ai_poc_simple_filter(message_string) =
  var input_map = {}
  var output_map = {}
  var skip = false
  input_map = parseHL7(message_string)
  clear(output_map)
  if (input_map.MSA) do {
    if (input_map.MSA[0].MSA[3] == "ZZZ") {
      skip = true
    }
  }
  if (!skip) do {
    output_map.MSH = input_map.MSH
    output_map.MSA = input_map.MSA
  }
  clear(input_map)
  if (skip) "" else output_map as String
var result = ai_poc_simple_filter(payload)
---
result
